let renderTimeout = null;

const scheduleRender = function () {
  if (renderTimeout) {
    return;
  }
  renderTimeout = setTimeout(function () {
    let elements;
    renderTimeout = null;
    elements = document.querySelectorAll(".owo-mermaid-pending");
    elements.forEach(function (elm) {
      let code, id;
      code = elm.getAttribute("data-code");
      id = "mermaid_" + Math.random().toString(36).slice(2, 9);
      elm.classList.remove("owo-mermaid-pending");
      try {
        const isDark = !(commonData.themeColor === 1 || commonData.themeColor === 2);
        mermaid.initialize({
          startOnLoad: false,
          theme: isDark ? 'dark' : 'default',
          securityLevel: 'loose',
          fontFamily: 'monospace'
        });
        mermaid.render(id, code).then(function ({ svg }) {
          elm.innerHTML = svg;
          if (typeof m !== "undefined" && typeof m.redraw === "function") {
            m.redraw();
          }
        }).catch(function (err) {
          console.error("Mermaid 渲染失败:", err);
          elm.innerHTML = `<pre style="color:#ff6b6b;font-size:0.9rem;white-space:pre-wrap;word-break:break-all;margin:0;">${err.message}</pre>`;
          if (typeof m !== "undefined" && typeof m.redraw === "function") {
            m.redraw();
          }
        });
      } catch (e) {
        console.error(e);
      }
    });
  }, 50);
};

let renderAbcTimeout = null;

const scheduleRenderAbc = function () {
  if (renderAbcTimeout) {
    return;
  }
  renderAbcTimeout = setTimeout(function () {
    let elements;
    renderAbcTimeout = null;
    elements = document.querySelectorAll(".owo-abc-pending");
    elements.forEach(function (elm) {
      const code = elm.getAttribute("data-code");
      elm.classList.remove("owo-abc-pending");
      const audioContainer = elm.parentElement ? elm.parentElement.querySelector(".owo-abc-audio-container") : null;
      try {
        const visualObjArray = abcjs.renderAbc(elm, code, {
          responsive: "resize"
        });
        if (audioContainer && visualObjArray && visualObjArray.length > 0) {
          const visualObj = visualObjArray[0];
          if (abcjs.synth.supportsAudio()) {
            const synthControl = new abcjs.synth.SynthController();
            const cursorControl = {
              onStart: function () {
                console.log("播放开始");
              },
              onFinished: function () {
                console.log("播放结束");
                const selected = document.querySelectorAll(".abcjs-note_selected");
                selected.forEach(el => el.classList.remove("abcjs-note_selected"));
              },
              onEvent: function (event) {
                if (!event) return;
                const selected = document.querySelectorAll(".abcjs-note_selected");
                selected.forEach(el => el.classList.remove("abcjs-note_selected"));
                if (event.elements) {
                  event.elements.forEach(function (elementList) {
                    elementList.forEach(function (elm) {
                      elm.classList.add("abcjs-note_selected");
                    });
                  });
                }
              }
            };
            synthControl.load(audioContainer, cursorControl, {
              displayLoop: false,
              displayRestart: true,
              displayPlay: true,
              displayProgress: true,
              displayWarp: false
            });
            const createSynth = new abcjs.synth.CreateSynth();
            createSynth.init({
              visualObj: visualObj,
              soundFontUrl: window.location.origin + "/statics/soundfont/"
            }).then(function () {
              synthControl.setTune(visualObj, false).then(function () {
                console.log("ABCJS 乐谱合成音频就绪");
              }).catch(function (synthErr) {
                console.error("加载音乐音轨失败:", synthErr);
              });
            }).catch(function (createErr) {
              console.error("生成音乐合成器失败:", createErr);
            });
          } else {
            audioContainer.innerHTML = `<div style="font-size:0.8rem;color:#ff6b6b;padding:0.5rem 0;">当前环境不支持 Web Audio API，无法播放音频。</div>`;
          }
        }
        if (typeof m !== "undefined" && typeof m.redraw === "function") {
          m.redraw();
        }
      } catch (err) {
        console.error("ABCJS 渲染失败:", err);
        elm.innerHTML = `<pre style="color:#ff6b6b;font-size:0.9rem;white-space:pre-wrap;word-break:break-all;margin:0;">${err.message}</pre>`;
        if (typeof m !== "undefined" && typeof m.redraw === "function") {
          m.redraw();
        }
      }
    });
  }, 50);
};

